# -*- coding: utf-8 -*-
"""論將第四 — 日本語訳。"""

TITLE = '第四篇　論將（ろんしょう）'
HEAD = '''五段。冒頭の一句が「将」を定める——「それ文武を総ぶる者は軍の将なり、剛柔を兼ぬる者は兵の事なり」。続くのが全書で最も名高い判断である。<b>「凡そ人の将を論ずるや、常に勇に観る。勇の将に於けるは、乃ち数分の一のみ」。</b>世間は将を論ずるのに勇ばかりを見るが、勇は将の力量のうち何分の一かにすぎない。勇なる者は必ず軽々しく合わせ、軽々しく合わせて利を知らぬのでは駄目である。そして<b>「将の慎む所の者五」</b>——理（衆を治むること寡を治むるがごとし）、備（門を出ずるに敵を見るがごとし）、果（敵に臨みて生を懐わず）、戒（克つといえども始めて戦うがごとし）、約（法令省きて煩わさず）。四庫提要が『呉子』を「持論すこぶる正に詭（たが）わず」と褒めたとき、引いたのがこの五字である。

第二段は<b>「四機」</b>——気機・地機・事機・力機。三軍の衆、百万の師、張り設ける軽重が一人にかかる、これが気機。路狭く道険しく、名山大塞、十夫の守る所を千夫も過ぎられぬ、これが地機。よく間諜を行い、軽兵を往来させ、その衆を分散させ、君臣を相怨ませる、これが事機。車は堅く舟は利く、士は戦陳に習い馬は馳逐に閑（な）れる、これが力機。この四つを知ってはじめて将たりうるが、なお威・徳・仁・勇が下を率い衆を安んずるに足らねばならぬ——「これを得れば国強く、これを去れば国亡ぶ」、これを良将という。

第三段は三つの威。鼙鼓金鐸は耳を威し、旌旗麾幟は目を威し、禁令刑罰は心を威す。三者立たずんば、その国ありといえども必ず敵に敗れる。第四段は<b>敵将の弱点十二条の一覧</b>——愚にして人を信ずれば詐りて誘うべく、貪りて名を忽（ゆるが）せにすれば貨して賂うべく、軽変にして謀なければ労して困しむべく、上富み下貧しければ離して間すべく……最後の一条は過失ではなく弛みである。「停まること久しくして移らず、将士懈怠し、その軍備えざれば、潜みて襲うべし」。末段は全書で最も実用的である。両軍相望んで相手の将が誰か分からぬ、どうやって見るか。賤しくて勇なる者に軽鋭を将（ひき）いさせて試させる——<b>ただし負けてこいと命じる</b>。追ってきても行き過ぎず、利を見ても知らぬふりをするなら智将、戦うな。衆が讙譁（かんか）し、追い付けぬことを恐れ、利を得られぬことを恐れるなら愚将、衆くとも獲るべし。<b>わざと負ける小競り合い一回と引き換えに、相手の将の履歴書を手に入れる。</b>'''

PARA = {
 'p4-1': '呉子が言った、「それ文と武とを総べる者が軍の将であり、剛と柔とを兼ねる者が兵（いくさ）の事である。およそ人が将を論ずるとき、常に勇に目をつける。だが勇の、将における分は、数分の一にすぎない。勇なる者は必ず軽々しく合わせ、軽々しく合わせて利を知らぬのでは、まだ可ではない。ゆえに将の慎む所の者は五つ。一に理、二に備、三に果、四に戒、五に約。理とは、衆を治めること寡を治めるがごとくすること。備とは、門を出るのに敵を見るがごとくすること。果とは、敵に臨んで生を懐（おも）わぬこと。戒とは、克ってもなお始めて戦うがごとくあること。約とは、法令が省けて煩わしくないこと。命を受けて辞さず、敵を破ってはじめて返ることを言う——これが将の礼である。ゆえに師を出す日には、死の栄あって、生の辱なし」。（「文武を総ぶ」は文事と武備を一手に握ること。「生を懐わず」は生き延びる含みを持たぬこと。「約」は簡約で、法令の条目が少ないこと。兵書が「勇」の重みをこれほど下げるのは珍しい。五つのうち「戒とは、克ってもなお始めて戦うがごとく」が最も呉起らしい——勝ったあとを第一戦として戦えということ。二本はともに「故師出之日」に作り、底本は「故出師之日」。義は同じなので底本に従う。叢刊本はさらに「之日」を「之曰」に作る、形訛。四庫本は「受命而不辞」の下に「家」字がある。）',
 'p4-2': '呉子が言った、「およそ兵には四つの機（かなめ）がある。一に気機、二に地機、三に事機、四に力機。三軍の衆、百万の師、張り設ける軽重が一人に在る——これを気機という。路は狭く道は険しく、名山大塞、十夫の守る所を千夫も過ぎられぬ——これを地機という。よく間諜を行い、軽兵を往来させ、その衆を分散させ、その君臣を相怨ませ、上下を相咎めさせる——これを事機という。車は管轄（軸の鍵）堅く、舟は櫓楫（ろかい）利く、士は戦陳に習い、馬は馳逐に閑（な）れる——これを力機という。この四つを知ってこそ、将となることができる。しかもなおその威・徳・仁・勇は、必ず下を率い衆を安んじ、敵を怖れさせ疑いを決するに足りねばならぬ。令を施して下は犯えず、在る所に寇（あだ）は敢えて敵せぬ。これを得れば国は強く、これを去れば国は亡ぶ。これを良将という」。（「機」は枢・転換点。「管轄」は車軸の両端の鉄の鍵で、輪が脱けぬよう押さえるもの。「櫓楫」は大櫂と小櫂。四機は人為で動かせる四つの場所——人の心、地形、離間、器械と訓練。気機が第一に置かれ、しかもそれは一人にしか係らないので、続いてその一人に必要な四つが説かれる。四庫本は「施令而下不犯」を「下不敢犯」、「所在寇不敢敵」を「所在而寇不敢敵」に作る。底本はここで「閒」の字を用いるが、本頁は書中の多数に従って「閑」とした。巻末参照。）',
 'p4-3': '呉子が言った、「それ鼙鼓（へいこ）と金鐸（きんたく）は耳を威す所以のもの、旌旗と麾幟は目を威す所以のもの、禁令と刑罰は心を威す所以のものである。耳は声に威されるから、声は清らかでなければならぬ。目は色に威されるから、色は明らかでなければならぬ。心は刑に威されるから、刑は厳しくなければならぬ。この三つが立たねば、その国ありといえども、必ず敵に敗れる。ゆえに言う、将の麾（さしまね）く所、従い移らざるはなく、将の指す所、前んで死せざるはなし」。（「鼙」は軍中の小鼓、「鐸」は舌のある大鈴で、鳴らして止める。「麾幟」は指揮に用いる旗。耳・目・心の三筋にそれぞれ一つの器具を配し、それぞれに一つの基準——清・明・厳——を与える。この一段が実際に説いているのは号令の感じ取りやすさである。はっきり聞こえ、はっきり見え、本当に怖くなければ、指揮は人に届かない。底本はここで縦組み用の冒号「︰」を用いるが、本頁は「：」に改めた。）',
 'p4-4': '呉子が言った、「およそ戦いの要は、必ずまずその将を占（はか）りその才を察し、形に因りて権を用いる。さすれば労せずして功が挙がる。その将が愚にして人を信ずるなら、詐りて誘うべし。貪りて名を忽せにするなら、貨して賂うべし。軽々しく変じて謀なきなら、労して困しますべし。上は富みて驕り下は貧しくて怨むなら、離して間（へだ）つべし。進退に疑い多くその衆が依る所なきなら、震わせて走らすべし。士がその将を軽んじ帰る志があるなら、易きを塞ぎ険しきを開いて、邀（むか）え取るべし。進む道が易く退く道が難いなら、来らせて前ませるべし。進む道が険しく退く道が易いなら、薄（せま）って撃つべし。軍を下湿の地に居らせ水の通う所なく、霖雨がしばしば至るなら、灌いで沈めるべし。軍を荒れた沢に居らせ、草楚が幽穢で、風飆（つむじ風）がしばしば至るなら、焚いて滅ぼすべし。停まること久しくして移らず、将士が懈怠し、その軍が備えぬなら、潜んで襲うべし」。（「その将を占る」は相手の将その人を見積もること。「形に因りて権を用いる」は現れた様子に応じて臨機の手を打つこと。「貨して賂う」は財物で買うこと。「易きを塞ぎ険しきを開く」は良い道を塞ぎ悪い道を残して、悪い道を通らせること。「草楚幽穢」は雑木や野草の茂り。十二条のうち前の六条は敵将の性情を見、後の六条は敵が軍をどこに置いているかを見る。最後の一条は失敗ではなく弛みで——長く陣を張って自分が緩むのは、最もありふれ、最も気づきにくい。四庫本は「因形用権」を「因其形而用其権」に作る。）',
 'p4-5': '武侯が問うた、「両軍が相望み、その将がどんな者か分からぬ。わたしはこれを相（み）たい、その術はどうか」。呉起が答えた、「賤しくて勇なる者に、軽鋭を将いてこれを嘗（ため）させます。務めるのは北（に）げることで、得ることを務めさせません。そして敵の来る様子を観ます。一坐一起が法度にかない、北げる兵を追うときには追い付けぬふりをし、利を見ては知らぬふりをする——そのような将は智将と名づけ、与に戦ってはなりません。もしその衆が讙譁（かまびす）しく、旌旗が煩乱し、その卒が自ら行き自ら止まり、その兵が或いは縦に或いは横に、北げる兵を追うには追い付けぬことを恐れ、利を見ては得られぬことを恐れるなら、これは愚将で、衆くとも獲ることができます」。（「これを相る」は人を見立てること。「北げるに務め、得るに務めず」がこの試しの肝——遣わされた者は負けてこいと命じられている。わざと負ける一回の小接触と引き換えに、相手の将の素性を持ち帰る。全書で最も実用的な一段であり、呉起らしさの最もよく出た一段でもある。彼は相手の兵が何人かを問わず、相手の将が誰かを問う。四庫本は「勿与戦矣」を「勿与戦也」に作る。）',
}
